package glitch

import data.glitch_lib

sensitive_keywords := {"password", "secret", "token", "key", "credential", "auth", "passphrase", "pwd", "pass", "accessKey", "secretKey", "privateKey", "truststore"}

non_sensitive_keywords := {"authenticator", "authorizer", "type", "path", "xml", "file", "template"}

is_sensitive_name(name) {
    lower_name := lower(name)
    kw := sensitive_keywords[_]
    contains(lower_name, kw)
    not is_non_sensitive(lower_name)
}

is_non_sensitive(lower_name) {
    nkw := non_sensitive_keywords[_]
    contains(lower_name, nkw)
}

Glitch_Analysis[result] {
    vars := glitch_lib.all_variables(input)
    var := vars[_]
    is_sensitive_name(var.name)
    var.value.ir_type == "String"
    count(var.value.value) > 0
    not glitch_lib.has_variable_reference(var.value)
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid embedding sensitive data directly in code. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    attrs := glitch_lib.all_attributes(input)
    attr := attrs[_]
    is_sensitive_name(attr.name)
    attr.value.ir_type == "String"
    count(attr.value.value) > 0
    not glitch_lib.has_variable_reference(attr.value)
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid embedding sensitive data directly in code. (CWE-798)"
    }
}

